-- --- 4. the deity’s own list of permitted leaves ---------------------------
-- It agreed with neither the book nor the archana rows: devadaaru where the
-- archana has aamalakee, gaNDakee where the archana has gaNDavee and the book
-- has gaNDalee. Three lists that should be one.
update public.deities set
  permitted_offerings = jsonb_set(permitted_offerings::jsonb, '{leaves}', '["macī","bṛhatī","bilva","dūrvā","durdhūra","badarī","apāmārga","tulasī","cūta","karavīra","viṣṇukrānta","āmalakī","maruvaka","sindhūra","jātī","gaṇḍalī","śamī","bhṛṅgarāja","arjuna","arka","dāḍimī"]'::jsonb),
  updated_at = now()
 where id = 'ganesha';

-- --- 5. record what changed and why ------------------------------------------
update public.pooja_steps set
  source_ref = 'Sampradaya Vratha Pooja Vidhi (Giri), p.63-64, ekavimshati patrapoojaa. Order and pairing follow the book, which puts ekadanta/daaDimee last where this app had it twelfth. Four offerings corrected: durdhoora for dhattoora (two names for Datura metel), sindhoora for sindhuvaara, gaNDalee for gaNDavee, and bhRngaraaja for ashvattha -- the last being the only one of the seven non-alliterating pairs that was actually wrong, the other six being paired the same way in the book. gaNDalee is left without a botanical identification rather than inheriting the one recorded for gaNDavee, which is a different word. Transcribed from a photograph of the printed page; no round-trip proof, diffed against the previous pairing before it was written.',
  verified_by = null, verified_at = null, updated_at = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)';

update public.pooja_steps set
  source_ref = 'Sampradaya Vratha Pooja Vidhi (Giri), p.65, ekavimshati puSHpapoojaa. Order confirmed identical. Two offerings corrected: durdhoora for dhattoora, and shyaamaka for shamyaaka -- the same four syllables in a different order. Transcribed from a photograph of the printed page; no round-trip proof, diffed against the previous pairing before it was written.',
  verified_by = null, verified_at = null, updated_at = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Pushpa Pooja (21 Flowers)';

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- Nothing parked, 1..21, no gap, no repeat.
  select count(*) into n from public.archana_items where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)') and seq >= 1000;
  if n > 0 then raise exception '% leaf offerings were left parked', n; end if;
  select (max(seq) - min(seq) + 1) - count(*) into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)');
  if n <> 0 then raise exception 'the leaf sequence is not dense'; end if;
  select count(*) into n from public.archana_items where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)');
  if n <> 21 then raise exception 'expected 21 leaves, found %', n; end if;
  -- The one real mismatch is gone, in all three scripts.
  select count(*) into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)') and offering_deva like '%अश्वत्थ%';
  if n > 0 then raise exception 'the ashvattha leaf is still paired with bhringarajatkata'; end if;
  select count(*) into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)')
     and position('भृंगराजत्कटाय' in invoked_name_deva) > 0
     and offering_deva like '%भृंगराज%';
  if n <> 1 then raise exception 'bhringarajatkata is not paired with the bhringaraja leaf'; end if;
  -- Ekadanta is last, as the book has it.
  select seq into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)') and position('एकदंताय' in invoked_name_deva) > 0;
  if n <> 21 then raise exception 'ekadanta/dadimi is at seq %, expected 21', n; end if;
  -- The flower transcription error is gone.
  select count(*) into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Pushpa Pooja (21 Flowers)') and offering_deva like '%शम्याक%';
  if n > 0 then raise exception 'shamyaaka is still in the flower list'; end if;
  select count(*) into n from public.archana_items
   where pooja_step_id = (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Pushpa Pooja (21 Flowers)') and offering_deva like '%श्यामक%';
  if n <> 1 then raise exception 'shyaamaka is not in the flower list'; end if;
  -- Neither list still calls the plant dhattoora.
  select count(*) into n from public.archana_items
   where pooja_step_id in ((select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Patra Pooja (21 Leaves)'), (select id from public.pooja_steps where pooja_id = 'ganesha_standard' and step_title_en = 'Pushpa Pooja (21 Flowers)')) and offering_deva like '%धत्तूर%';
  if n > 0 then raise exception '% offerings still say dhattoora', n; end if;
  -- The deity list and the archana rows now agree, 21 to 21.
  select jsonb_array_length(permitted_offerings::jsonb -> 'leaves') into n
    from public.deities where id = 'ganesha';
  if n <> 21 then raise exception 'the deity leaf list has % entries', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;

